output_text:
[
  {
    "id": "no_carts_between_shelves",
    "text": "Shopping carts are prohibited in single-file shelf canyons where shelves are on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfCanyon": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfCanyon"
        ]
      }
    }
  },
  {
    "id": "no_pushing_cart_into_canyon",
    "text": "At the mouth of a single-file shelf aisle, a shopper must not push the cart north into the aisle.",
    "abstraction": {
      "state_properties": {
        "pedestrianAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "pushCartNorthFromMouth": {
          "pre": {
            "and": [
              "hasCart",
              "pedestrianAisleMouth",
              "N"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartNorthFromMouth"
    }
  },
  {
    "id": "no_cart_item_pick_in_canyon",
    "text": "Items in single-file shelf canyons must not be taken while holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfCanyon": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfCanyon",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a shopper parks or releases a cart, they are obliged to retrieve a cart again before leaving.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartPickup": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartDrop",
      "discharge": "cartPickup"
    }
  },
  {
    "id": "no_wandering_without_cart",
    "text": "After entering the store, shoppers may be without a cart only at the cart bay, at a cart parking mouth, or inside a single-file shelf canyon.",
    "abstraction": {
      "state_properties": {
        "cartBayArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartParkZone": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfCanyon": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "allowedOnFootArea": {
          "or": [
            "cartBayArea",
            "cartParkZone",
            "singleFileShelfCanyon"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "allowedOnFootArea"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_at_open_shelves",
    "text": "Shelf interactions at trolley-accessible shelf faces must be done with a cart; only single-file canyon shelves may be served on foot.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfCanyon": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfCanyon"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openShelfFace",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "return_after_canyon_pick",
    "text": "After taking an item on foot from a single-file shelf canyon, the shopper must return to and pick up the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfCanyon": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "pedestrianCanyonPick": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileShelfCanyon",
              "INTERACT"
            ]
          },
          "post": null
        },
        "cartPickup": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pedestrianCanyonPick",
      "discharge": "cartPickup"
    }
  },
  {
    "id": "park_only_at_aisle_mouths",
    "text": "Carts may be released only at designated wide parking mouths for pedestrian shelf aisles.",
    "abstraction": {
      "state_properties": {
        "cartParkZone": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartDropOutsideParkZone": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              {
                "not": "cartParkZone"
              }
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartDropOutsideParkZone"
    }
  }
]
